import java.util.*;

class Solution {
    public int secondLargest(int[] nums) {
        long first = Long.MIN_VALUE, second = Long.MIN_VALUE; // MIN_VALUE = not set yet
        for (int x : nums) {
            if (x > first) {
                second = first;        // old max becomes runner-up
                first = x;
            } else if (x < first && x > second) {
                second = x;            // strictly between: new runner-up
            }
        }
        return second == Long.MIN_VALUE ? -1 : (int) second;
    }
}

